package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ScienceLiveExamChemOrgBank2 {
  private const val T = "ලෝහ විද්‍යාව, හයිඩ්‍රොකාබන, බහුඅවයවික හා කාර්මික රසායනය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String = "කාබනික, ලෝහ හා කාර්මික රසායනයට අදාළ නිවැරදි කරුණකි."
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("ධාරා ඌෂ්මකයෙන් ලබා ගන්නා 'වත්කරන ලද යකඩ' (Pig iron) වල කාබන් ප්‍රතිශතය ආසන්න වශයෙන් 4% කි. ඉන්පසු එය 'වානේ' (Steel) බවට පත් කිරීමට කරන්නේ කුමක්ද?", "ද්‍රව යකඩ තුළට ඔක්සිජන් යවා අතිරික්ත කාබන් CO₂ ලෙස ඉවත් කිරීම", "තවත් කාබන් එකතු කිරීම", "සිසිල් ජලය වත් කිරීම", "වැලි මිශ්‍ර කිරීම", "මෘදු වානේවල කාබන් 0.25% ක් පමණ අඩංගු බැවින් එය නම්‍යශීලී හා ශක්තිමත් වේ."),
    q("ස්වභාවික හිමැටයිට් යකඩ නිධියක් වෙනුවට ශ්‍රී ලංකාවේ බහුලව සොයා ගෙන ඇති හුණුගල් (CaCO₃) භාවිත කරන ප්‍රධාන කර්මාන්තයක් වන්නේ කුමක්ද?", "සිමෙන්ති හා අළු හුණු නිෂ්පාදනය", "විදුලි බැටරි නිෂ්පාදනය", "ප්ලාස්ටික් නිෂ්පාදනය", "පෙට්‍රල් පිරිපහදුව", "පුත්තලම හා අරුවක්කාලු හුණුගල් නිධි සිමෙන්ති කර්මාන්තයට යොදා ගනී."),
    q("සෝල්වේ ක්‍රමය (Solvay process) මඟින් කාර්මිකව නිපදවන වැදගත් ක්ෂාරීය ලවණය කුමක්ද?", "සෝඩියම් කාබනේට් (Na₂CO₃ - සෝඩා අළු)", "සල්ෆියුරික් අම්ලය", "ඇමෝනියා", "කැල්සියම් ක්ලෝරයිඩ්", "හුණුගල්, NaCl හා ඇමෝනියා අමුද්‍රව්‍ය ලෙස භාවිත කෙරේ."),
    q("කිසියම් ලෝහ නිස්සාරණයකදී සල්ෆයිඩ් ලෝපසක් (උදා: ZnS) වාතය තුළ දැඩි ලෙස රත් කර ඔක්සයිඩය බවට හැරවීමේ ක්‍රියාවලිය කුමක්ද?", "භස්මීකරණය / කර කිරීම (Roasting)", "විද්‍යුත් විච්ඡේදනය", "ආසවනය", "පෙරීම", "2ZnS + 3O₂ → 2ZnO + 2SO₂."),
    q("ලෝහ සක්‍රීයතාව අනුව කාබන් මඟින් ඔක්සිහරණය කර නිස්සාරණය කළ හැකි ලෝහ යුගලයක් වන්නේ කුමක්ද?", "යකඩ (Fe) සහ සින්ක් (Zn)", "සෝඩියම් (Na) සහ පොටෑසියම් (K)", "කැල්සියම් (Ca) සහ මැග්නීසියම් (Mg)", "ඇලුමිනියම් (Al) සහ ලිතියම් (Li)", "සක්‍රියතා ශ්‍රේණියේ කාබන්ට පහළින් ඇති Zn, Fe, Pb, Cu කාබන් මඟින් ඔක්සිහරණය කළ හැක."),
    q("සොලරයිස් හෝ සාමාන්‍ය රසායනිකව නිස්සාරණය නොකර ස්වභාවයේ ශුද්ධ මූලද්‍රව්‍ය ලෙසම (Native state) හමු වන ලෝහ මොනවාද?", "රන් (Au) සහ ප්ලැටිනම් (Pt)", "සෝඩියම් සහ කැල්සියම්", "ඇලුමිනියම් සහ මැග්නීසියම්", "යකඩ සහ සින්ක්", "මේවා වාතය, ජලය හෝ අම්ල සමඟ ප්‍රතික්‍රියා නොකරන තරම් නිෂ්ක්‍රීය වේ."),
    q("තඹ (Cu) පිරිපහදු කිරීමේ විද්‍යුත් විච්ඡේදන ක්‍රමයේදී අපිරිසිදු තඹ කුට්ටිය හා පිරිසිදු තුනී තඹ පත්‍රය සම්බන්ධ කරන අග්‍ර පිළිවෙළින් මොනවාද?", "අපිරිසිදු තඹ → ඇනෝඩය, පිරිසිදු තඹ → කැතෝඩය", "අපිරිසිදු තඹ → කැතෝඩය, පිරිසිදු තඹ → ඇනෝඩය", "දෙකම ඇනෝඩයට", "දෙකම කැතෝඩයට", "පිරිසිදු තඹ කැතෝඩය මත තැන්පත් වන අතර රන්/රිදී අපද්‍රව්‍ය 'ඇනෝඩ මඩ' ලෙස පතුලේ රැඳේ."),
    q("බොක්සයිට් පිරිපහදු කිරීමේදී මෙන් ඇලුමිනියම් නිස්සාරණයේදී භාවිත කරන ප්‍රධාන ඔක්සිහරණ ක්‍රමය කුමක්ද?", "විලීන ඇලුමිනා විද්‍යුත් විච්ඡේදනය කිරීම", "කාබන් සමඟ රත් කිරීම", "හයිඩ්‍රජන් වායුව යැවීම", "වැලි සමඟ උණු කිරීම", "Al₂O₃ හි Al³⁺ අයන කැතෝඩයේදී ඉලෙක්ට්‍රෝන 3 ක් ගෙන ද්‍රව ඇලුමිනියම් බවට පත් වේ."),
    q("මැග්නීසියම් 10% ක් පමණ හා ඇලුමිනියම් 90% ක් අඩංගු සැහැල්ලු හා මල නොබැඳෙන මිශ්‍ර ලෝහය හඳුන්වන්නේ කුමන නමින්ද?", "මැග්නැලියම් (Magnalium)", "පිත්තල", "ලෝකඩ", "සෝල්ඩර්", "කැමරා කොටස්, තරාදි බාහු හා ගුවන් යානා උපාංග සෑදීමට යොදා ගනී."),
    q("මිනිසා විසින් නිපදවන පළමු කෘත්‍රිම ප්ලාස්ටික් වැනි කෘත්‍රිම තන්තුමය බහුඅවයවිකය වන නයිලෝන් (Nylon) යොදා ගන්නේ කුමන නිෂ්පාදන සඳහාද?", "මසුන් ඇල්ලීමේ දැල්, කඹ, දත් බුරුසු කෙඳි හා පැරෂුට්", "විදුලි සන්නායක කම්බි", "වීදුරු ජනෙල්", "සිමෙන්ති බදාම", "නයිලෝන් යනු ඉහළ ආතන්‍ය ශක්තියක් ඇති පොලිඇමයිඩ් බහුඅවයවිකයකි."),
    q("C₄H₁₀ යන අණුක සූත්‍රයට අයත් බියුටේන් අණුවේ ව්‍යුහාත්මක සමාවයවික (Structural isomers) ගණන කීයද?", "2 (n-බියුටේන් හා 2-මෙතිල්ප්‍රොපේන්)", "1", "3", "4", "අණුක සූත්‍රය සමාන නමුත් ව්‍යුහ සූත්‍රය වෙනස් සංයෝග සමාවයවික නම් වේ."),
    q("එතීන් (C₂H₄) හයිඩ්‍රජන් වායුව සමඟ නිකල් (Ni) උත්ප්‍රේරකය හමුවේ 150°C දී ප්‍රතික්‍රියා කළ විට සෑදෙන සංයෝගය කුමක්ද?", "ඊතේන් (C₂H₆)", "මීතේන් (CH₄)", "එතනෝල්", "පොලිතීන්", "අසංතෘප්ත එළවළු තෙල් හයිඩ්‍රජනීකරණය කර මාගරින් සෑදීමේදී ද මෙම ප්‍රතික්‍රියාව භාවිත වේ."),
    q("අසංතෘප්ත එතීන් (C₂H₄) උත්ප්‍රේරකයක් හමුවේ අධි උෂ්ණත්වය හා පීඩනයේදී හුමාලය (H₂O) සමඟ ප්‍රතික්‍රියා කර නිපදවන කාබනික සංයෝගය කුමක්ද?", "එතනෝල් (C₂H₅OH)", "ඇසිටික් අම්ලය", "ඊතේන්", "මීතේන්", "C₂H₄(g) + H₂O(g) → C₂H₅OH(g) (කාර්මිකව එතනෝල් නිපදවීම)."),
    q("වායුමය හයිඩ්‍රොකාබන අතරින් ත්‍රිත්ව කාබන්-කාබන් බන්ධනයක් (C≡C) ඇති, ලෝහ කැපීමේ ඔක්සි-ඇසිටිලීන් දැල්ල සඳහා ගන්නා වායුව කුමක්ද?", "ඉතයින් / ඇසිටිලීන් (C₂H₂)", "එතීන් (C₂H₄)", "මීතේන් (CH₄)", "ප්‍රොපේන් (C₃H₈)", "ඔක්සි-ඇසිටිලීන් දැල්ල 3000°C ට වැඩි උෂ්ණත්වයක් නිපදවයි."),
    q("පොලිප්‍රොපීන් (Polypropene) බහුඅවයවිකය නිපදවීම සඳහා යොදා ගන්නා ඒකාවයවිකය කුමක්ද?", "ප්‍රොපීන් (CH₃-CH=CH₂)", "ප්‍රොපේන්", "එතීන්", "ස්ටයිරීන්", "ශක්තිමත් කඹ, කාපට්, යෝගට් කෝප්ප හා වාහන බම්පර් සෑදීමට යොදා ගනී."),
    q("පහත දැක්වෙන බහුඅවයවික අතුරින් 'ස්වාභාවික බහුඅවයවිකයක්' වන්නේ කුමක්ද?", "ප්‍රෝටීන, පිෂ්ටය සහ සෙලියුලෝස්", "පොලිතීන්", "PVC", "නයිලෝන්", "ජීවී සෛල තුළ ස්වභාවිකව සංස්ලේෂණය වන බහුඅවයවික ස්වාභාවික බහුඅවයවික වේ."),
    q("කෘත්‍රිම ප්ලාස්ටික් (උදා: පොලිතීන්) පරිසරයේ සියවස් ගණනාවක් නොදිරා පැවතීමට ප්‍රධාන හේතුව කුමක්ද?", "දිගු කාබන්-කාබන් බන්ධන ක්ෂුද්‍රජීවී එන්සයිම මගින් බිඳ දැමිය නොහැකි වීම", "ඒවා ජලයේ දිය වීම", "ඒවා ඉතා සැහැල්ලු වීම", "ඒවා ලෝහ වීම", "මෙය ප්‍රබල පාරිසරික අපද්‍රව්‍ය ගැටලුවක් ඇති කරයි."),
    q("බොරතෙල් භාගික ආසවනයේදී ලැබෙන ඉහළම තාපාංකය ඇති අවසාන අර්ධ-ඝන කළු අවශේෂය කුමක්ද?", "බිටුමන් (තාර / ඇස්ෆෝල්ට්)", "පෙට්‍රල්", "භූමිතෙල්", "නැප්තා", "බිටුමන් මහාමාර්ග කාපට් කිරීමට හා වහල ජල-ආරක්ෂණ ආලේපන සඳහා ගනී."),
    q("බොරතෙල් භාගික ආසවනයේදී ප්ලාස්ටික් හා රසායනික ද්‍රව්‍ය නිපදවීම සඳහා ප්‍රධාන අමුද්‍රව්‍ය ලෙස යොදා ගන්නා භාගය කුමක්ද?", "නැප්තා (Naphtha)", "බිටුමන්", "ලිහිසි තෙල්", "ඩීසල්", "නැප්තා භාගය Cracking ක්‍රියාවලියෙන් එතීන් හා ප්‍රොපීන් නිපදවයි."),
    q("ජෙට් ගුවන් යානා ඉන්ධනය ලෙසත් ගෘහස්ථ ලාම්පු තෙල් ලෙසත් භාවිත කරන බොරතෙල් භාගය කුමක්ද?", "භූමිතෙල් (Kerosene / පැරෆින්)", "පෙට්‍රල්", "බිටුමන්", "LP ගෑස්", "භූමිතෙල් C₁₀ සිට C₁₆ දක්වා හයිඩ්‍රොකාබනවලින් සමන්විත වේ."),
    q("එතනෝල් (C₂H₅OH) ප්‍රබල ඔක්සිකාරකයක් වන ආම්ලික පොටෑසියම් ඩයික්‍රොමේට් (K₂Cr₂O₇) සමඟ රත් කළ විට සෑදෙන අම්ලය කුමක්ද?", "එතනොයික් අම්ලය (CH₃COOH)", "සල්ෆියුරික් අම්ලය", "මීතේන්", "කාබන් මොනොක්සයිඩ්", "එතනෝල් ඔක්සිකරණය වී ඇසිටික් අම්ලය සෑදෙන අතර තැඹිලි ද්‍රාවණය කොළ පැහැ වේ."),
    q("විනාකිරි යනු ජලයේ දිය කළ 5% ක පමණ කුමන කාබනික සංයෝගයද?", "එතනොයික් අම්ලය (ඇසිටික් අම්ලය)", "එතනෝල්", "මෙතනෝල්", "සිට්‍රික් අම්ලය", "ආහාර කල් තබා ගැනීමට හා අච්චාරු සෑදීමට විනාකිරි ගනී."),
    q("පළතුරු සුවඳැති කාබනික සංයෝග කාණ්ඩයක් වන 'එස්ටර' (Esters) සෑදෙන්නේ කුමන සංයෝග දෙක ප්‍රතික්‍රියා කිරීමෙන්ද?", "කාබොක්සිලික් අම්ලයක් සහ ඇල්කොහොලයක්", "ඇල්කේනයක් සහ ජලය", "ලෝහයක් සහ අම්ලයක්", "හැලජනයක් සහ භෂ්මයක්", "සාන්ද්‍ර H₂SO₄ උත්ප්‍රේරකය හමුවේ මෙම එස්ටරීකරණ ප්‍රතික්‍රියාව සිදුවේ."),
    q("රබර් වල්කනයිස් කිරීමේදී යොදා ගන්නා ප්‍රධාන මූලද්‍රව්‍යය සහ එමගින් ඇතිවන රසායනික ව්‍යුහය කුමක්ද?", "සල්ෆර්; රබර් දාම අතර සල්ෆර් හරස් බන්ධන", "ක්ලෝරීන්; අයනික දැලිස", "නයිට්‍රජන්; ත්‍රිත්ව බන්ධන", "කැල්සියම්; ලෝහක බන්ධන", "හරස් බන්ධන නිසා රබර් රත් වූ විට ඇලෙන සුලු බව නැති වී ගෙවීම අඩු වේ."),
    q("සබන් අණුවක ව්‍යුහය සැලකීමේදී තෙල් පැල්ලම් දිය කර ගන්නා කොටස හා ජලයට ආකර්ෂණය වන කොටස පිළිවෙළින් මොනවාද?", "ජලභීතික හයිඩ්‍රොකාබන වල්ගය සහ ජලකාමී අයනික හිස", "දෙකම ජලකාමී වේ", "දෙකම ජලභීතික වේ", "අයනික වල්ගය සහ ලෝහ හිස", "සබන් අණු මයිසෙල (Micelles) සාදා තෙල් කුණු ජලය සමඟ සෝදා හරී."),
    q("කිසියම් ලිපිඩයක් හෙවත් මේදයක් යනු ග්ලිසරෝල් සමඟ කුමන අම්ල සංයෝජනයෙන් සෑදුණු එස්ටරයක්ද?", "මේද අම්ල (දිගු දාම කාබොක්සිලික් අම්ල)", "හයිඩ්‍රොක්ලෝරික් අම්ලය", "ඇමයිනෝ අම්ල", "න්‍යෂ්ටික අම්ල", "එක් ග්ලිසරෝල් අණුවකට මේද අම්ල අණු තුනක් බැඳී ට්‍රයිග්ලිසරයිඩ් සාදයි."),
    q("වායුසමීකරණ හා ශීතකරණවල පැරණි CFC වායු වෙනුවට දැන් භාවිත කරන ඕසෝන් ස්තරයට අවම හානියක් කරන හයිඩ්‍රොකාබන ව්‍යුත්පන්න කුමක්ද?", "HFC (හයිඩ්‍රොෆ්ලුවොරෝකාබන) හෝ ස්වාභාවික හයිඩ්‍රොකාබන", "ක්ලෝරීන් වායුව", "කාබන් මොනොක්සයිඩ්", "සල්ෆර් ඩයොක්සයිඩ්", "HFC වල ක්ලෝරීන් නොමැති නිසා ඕසෝන් විනාශ නොකරයි."),
    q("ශ්‍රී ලංකාවේ කලුගල්, හුණුගල් හා වැලි හැරුණු විට ලංකාවේ ප්‍රධාන පිඟන් මැටි හා පෝසිලේන් කර්මාන්තයට යොදා ගන්නා ඛනිජය කුමක්ද?", "කෙයොලින් (කිරිමැටි) සහ ෆෙල්ඩ්ස්පාර්", "බොක්සයිට්", "මයිකා පමණක්", "ඉල්මනයිට්", "මීටියාගොඩ කිරිමැටි හා කොස්ලන්ද ෆෙල්ඩ්ස්පාර් සෙරමික් කර්මාන්තයට වැදගත් වේ."),
    q("ලෝහයක් ලෙස ඉතා හොඳ විද්‍යුත් සන්නායකතාවක් ඇති අතරම විඛාදනයට ප්‍රතිරෝධී බැවින් අධි වෝල්ටීයතා විදුලි රැහැන් සඳහා භාවිත කරන්නේ කුමක්ද?", "ඇලුමිනියම් (වානේ කම්බියක් වටා)", "ඊයම්", "සෝඩියම්", "යකඩ පමණක්", "ඇලුමිනියම් සැහැල්ලු වන අතර තඹවලට වඩා ලාභදායීය."),
    q("පෙට්‍රල් වැනි හයිඩ්‍රොකාබන ඉන්ධන අසම්පූර්ණව දහනය වූ විට නිපදවෙන ඵල මොනවාද?", "කාබන් මොනොක්සයිඩ් (CO), කාබන් (දැලි) සහ ජලය", "CO₂ සහ O₂ පමණි", "හයිඩ්‍රජන් පමණි", "නයිට්‍රජන් සහ සල්ෆර්", "සංවෘත කාමරයක විදුලි ජනක යන්ත්‍ර ක්‍රියාත්මක කිරීම CO විෂ වීම නිසා මාරාන්තික වේ."),
    q("ජලයේ කඨිනත්වය නිර්ණය කිරීම සඳහා ප්‍රායෝගික පරීක්ෂණයකදී සමාන ජල නියැදිවලට එකතු කර හොඳින් සෙලවිය යුත්තේ කුමක්ද?", "සම්මත සබන් ද්‍රාවණය (බිංදු ගණන ගණන් කිරීම)", "ලුණු ද්‍රාවණය", "හයිඩ්‍රොක්ලෝරික් අම්ලය", "සීනි ද්‍රාවණය", "ස්ථිර පෙණ ස්තරයක් ඇති වීමට වැඩිම සබන් බිංදු ගණනක් අවශ්‍ය වන්නේ වැඩිම කඨින ජලයටය."),
    q("සාමාන්‍යයෙන් ගෘහස්ථ ජල නල පද්ධතිවල උණු වතුර නල හා වහල තහඩු සෑදීමට ගන්නා භාෂ්මික නොවන ප්ලාස්ටික් වර්ග කුමක්ද?", "uPVC සහ කෘත්‍රිම පොලිමර්", "සෝඩියම් ක්ලෝරයිඩ්", "ඇමෝනියම් නයිට්‍රේට්", "සීනි", "uPVC (Unplasticized PVC) දැඩි හා කල් පවතින බැවින් ජල නල සඳහා ගනී."),
    q("දී ඇති හයිඩ්‍රොකාබන අණු අතුරින් 'ප්‍රොපීන්' අණුවේ ව්‍යුහ සූත්‍රය නිවැරදිව දක්වා ඇත්තේ කුමක්ද?", "CH₃-CH=CH₂", "CH₃-CH₂-CH₃", "CH≡C-CH₃", "CH₂=CH₂", "ප්‍රොපීන්හි කාබන් 3 ක් සහ එක් ද්විත්ව බන්ධනයක් (C₃H₆) ඇත."),
    q("එතීන් (C₂H₄) අණුවේ කාබන් පරමාණු දෙක අතර හවුලේ බෙදාගෙන ඇති මුළු ඉලෙක්ට්‍රෝන ගණන කීයද?", "4 (ද්විත්ව බන්ධනය)", "2", "6", "8", "ද්විත්ව බන්ධනය ඉලෙක්ට්‍රෝන යුගල 2 කින් (ඉලෙක්ට්‍රෝන 4 කින්) සෑදී ඇත."),
    q("මීතේන් (CH₄) හා ඔක්සිජන් අතිරික්තයක පූර්ණ දහනය සඳහා තුලිත රසායනික සමීකරණය කුමක්ද?", "CH₄ + 2O₂ → CO₂ + 2H₂O", "CH₄ + O₂ → CO + 2H₂O", "CH₄ + O₂ → C + 2H₂O", "2CH₄ + O₂ → 2CO₂ + 4H₂", "ඕනෑම හයිඩ්‍රොකාබනයක පූර්ණ දහනයෙන් CO₂ හා H₂O පමණක් ලැබේ."),
    q("පොලිස්ටයිරීන් (Polystyrene) ප්ලාස්ටික් ෆෝම් ආහාර පෙට්ටි හා ඇසුරුම් සඳහා යොදා ගන්නේ එහි කුමන ගුණය නිසාද?", "වාතය රැඳි සැහැල්ලු ව්‍යුහය හා විශිෂ්ට තාප පරිවාරක ගුණය", "ඉහළ විද්‍යුත් සන්නායකතාව", "ඉහළ ඝනත්වය", "ජලයේ ඉක්මනින් දිය වීම", "කෙසේ වෙතත් තනි භාවිත පොලිස්ටයිරීන් පරිසර දූෂණයට ප්‍රබල හේතුවකි."),
    q("වාහනවල රේඩියේටරයේ හා කාර්මික බොයිලේරුවල කඨින ජලය භාවිත කිරීම නුසුදුසු වන්නේ ඇයි?", "අභ්‍යන්තරයේ CaCO₃ කබොල බැඳී තාප සන්නායකතාව අඩු වීම හා නල අවහිර වීම", "ජලය නිල් පැහැ වීම", "ලෝහ දිය වීම", "ජලය ගිනි ගැනීම", "කබොල නිසා ඉන්ධන නාස්තිය හා බොයිලේරු පුපුරා යාමේ අවදානම ඇති වේ."),
    q("නයිට්‍රජන්, පොස්පරස් සහ පොටෑසියම් යන NPK කෘත්‍රිම පොහොරවලින් ශාකවල ප්‍රෝටීන සංස්ලේෂණය හා පත්‍ර වර්ධනයට ප්‍රධාන වන්නේ කුමන මූලද්‍රව්‍යයද?", "නයිට්‍රජන් (N)", "පොටෑසියම් (K)", "කැල්සියම්", "සෝඩියම්", "නයිට්‍රජන් ඇමයිනෝ අම්ල හා හරිතප්‍රදවල අත්‍යවශ්‍ය සංඝටකයකි."),
    q("කිසියම් ලෝහ නිධියක් භෞතිකව කුඩු කර පිරිසිදු කරගත් පසු එහි ඇති වටිනා ලෝහමය ඛනිජය හඳුන්වන්නේ කුමන නමින්ද?", "ලෝපස (Ore)", "ලෝහ බොර (Slag)", "මිශ්‍ර ලෝහය", "අවක්ෂේපය", "ආර්ථික වශයෙන් ලාභදායීව ලෝහ නිස්සාරණය කළ හැකි ඛනිජය 'ලෝපස' වේ."),
    q("සින්ක් නිස්සාරණයේදී සින්ක් බ්ලෙන්ඩ් (ZnS) කර කර ලබාගන්නා ZnO උණුසුම්ව කෝක් (C) සමඟ ප්‍රතික්‍රියා කරවූ විට ලැබෙන වායුමය ලෝහය ඝනීභවනය කරන්නේ ඇයි?", "ප්‍රතික්‍රියා උෂ්ණත්වය (1000°C+) සින්ක්වල තාපාංකයට (907°C) වඩා වැඩි බැවින්", "සින්ක් වාතයට වඩා බර නිසා", "සින්ක් අලෝහයක් නිසා", "කාබන් දියවන නිසා", "සින්ක් වාෂ්ප වායු රහිත තත්ත්ව යටතේ සිසිල් කර ද්‍රව/ඝන සින්ක් ලබා ගනී."),
    q("වාතයේ ඇති නයිට්‍රජන් ඔක්සිඩ් (NOₓ) සහ නොදැවුණු හයිඩ්‍රොකාබන සූර්යාලෝකය හමුවේ ප්‍රතික්‍රියා කර නගරවල ඇති කරන අහිතකර තත්ත්වය කුමක්ද?", "ප්‍රකාශ රසායනික දුමාරය (Photochemical smog)", "හිම කුණාටු", "සුපෝෂණය", "ජල දූෂණය", "වාහනවල උත්ප්‍රේරක පරිවර්තක (Catalytic converters) මෙය අවම කරයි."),
    q("නවීන මෝටර් රථවල දුම් බටයේ සවි කර ඇති උත්ප්‍රේරක පරිවර්තකය (Catalytic converter) මඟින් විෂ සහිත CO හා NO වායු හරවන්නේ මොනවා බවටද?", "අඩු හානිකර CO₂ සහ N₂ වායු බවට", "SO₂ සහ H₂S බවට", "ක්ලෝරීන් සහ මීතේන් බවට", "ඇමෝනියා බවට", "ප්ලැටිනම් හා රෝඩියම් උත්ප්‍රේරක මෙහිදී භාවිත කෙරේ."),
    q("තඹ කම්බි, රිදී ආභරණ හා සින්ක් තහඩු අතරින් අධි වෝල්ටීයතා රැහැන්වලට වඩා ගෘහස්ථ විදුලි පරිපථ වයර් සඳහා බහුලව ගන්නේ කුමන ලෝහයද?", "තඹ (Copper)", "ඊයම්", "සින්ක්", "යකඩ", "තඹ රිදීවලට පසු හොඳම විද්‍යුත් සන්නායකය වන අතර ලාභදායී හා තන්‍ය වේ."),
    q("පිත්තල, ලෝකඩ, මල නොබැඳෙන වානේ සහ රසදිය ඇමැල්ගම් අතුරින් රසදිය ලෝහය අනිවාර්ය සංඝටකයක් වන්නේ කුමන මිශ්‍ර ලෝහයේද?", "දන්ත ඇමැල්ගම් (Dental amalgam)", "පිත්තල", "ලෝකඩ", "වානේ", "රිදී හා ටින් සමඟ රසදිය මිශ්‍ර කර දත් පිරවීමේ ඇමැල්ගම් සාදයි."),
    q("කිසියම් හයිඩ්‍රොකාබනයක අණුක සූත්‍රය C₅H₁₂ නම් එය අයත් ශ්‍රේණිය හා නම කුමක්ද?", "ඇල්කේන — පෙන්ටේන්", "ඇල්කීන — පෙන්ටීන්", "ඇල්කයින — පෙන්ටයින්", "ඇල්කොහොල — පෙන්ටනෝල්", "2n + 2 = 2(5) + 2 = 12 බැවින් CₙH₂ₙ₊₂ ආකාරයේ ඇල්කේනයකි."),
    q("C₄H₈ යන අණුක සූත්‍රය නිරූපණය කරන විවෘත දාම හයිඩ්‍රොකාබනය කුමක්ද?", "බියුටීන් (ඇල්කීනයක්)", "බියුටේන්", "ප්‍රොපේන්", "හෙක්සේන්", "CₙH₂ₙ (4 × 2 = 8) බැවින් ද්විත්ව බන්ධනයක් සහිත බියුටීන් වේ."),
    q("පොලිතීන් බෑග් වැනි තාප සුවිකාර්‍ය ප්ලාස්ටික් (Thermoplastics) ප්‍රතිචක්‍රීකරණය කිරීම පහසු වන්නේ ඇයි?", "දාම අතර හරස් බන්ධන නොමැති නිසා රත් කළ විට මෘදු වී උණු වීම", "ඒවා ජලයේ දිය වීම", "ඒවායේ ලෝහ බන්ධන තිබීම", "ඒවා කිසිදා උණු නොවීම", "උණු කර නැවත විවිධ අච්චුවලට වත් කර නව භාණ්ඩ සෑදිය හැක."),
    q("පරිසර හිතකාමී ඇසුරුම් සඳහා දැන් පොලිතීන් වෙනුවට භාවිතයට ගන්නා ජෛව හායනයට ලක්වන (Biodegradable) ප්ලාස්ටික් නිපදවන්නේ කුමකින්ද?", "ඉරිඟු පිෂ්ටය හා ශාක සෙලියුලෝස් වැනි ස්වාභාවික ද්‍රව්‍යවලින් (PLA ආදිය)", "ඛනිජ තෙල් තාරවලින්", "බැර ලෝහවලින්", "ඇස්බැස්ටස්වලින්", "ක්ෂුද්‍රජීවීන් මගින් මේවා කාබන් ඩයොක්සයිඩ් හා ජලය බවට ජීර්ණය කළ හැක."),
    q("සුළඟින් හෝ ජලයෙන් කොරල්පර හා ගල්පර ඛාදනය වීම මෙන්, නාගරික කිරිගරුඬ (CaCO₃) ප්‍රතිමා අම්ල වැසි නිසා දියවීමේ රසායනික ප්‍රතික්‍රියාව කුමක්ද?", "CaCO₃ + H₂SO₄ → CaSO₄ + H₂O + CO₂", "CaCO₃ + NaOH → Ca(OH)₂ + Na₂CO₃", "CaCO₃ + O₂ → CaO + CO₃", "CaCO₃ + H₂O → Ca + H₂CO₃", "අම්ල වැසිවල ඇති සල්ෆියුරික් හා නයිට්‍රික් අම්ල කාබනේට විඛාදනය කරයි."),
    q("දී ඇති ලෝහ යුගල අතුරින් විදුලි උපකරණවල 'විලායක කම්බිය' (Fuse wire) සෑදීමට වඩාත් සුදුසු අඩු ද්‍රවාංක මිශ්‍ර ලෝහය සාදන්නේ කුමන ලෝහද?", "ඊයම් සහ ටින්", "ටංස්ටන් සහ යකඩ", "තඹ සහ රන්", "ඇලුමිනියම් සහ ක්‍රෝමියම්", "අධික ධාරාවක් ගලා ගියහොත් උෂ්ණත්වය ඉහළ ගොස් ඉක්මනින් දිය වී පරිපථය විසන්ධි කළ යුතුය."),
    q("පෘථිවි කබොලෙන් නිස්සාරණය කරන යකඩ හා ඇලුමිනියම් සංසන්දනය කිරීමේදී ඇලුමිනියම් ප්‍රතිචක්‍රීකරණය කිරීම ආර්ථිකව අතිශයින් ලාභදායී වන්නේ ඇයි?", "නව බොක්සයිට් විද්‍යුත් විච්ඡේදනයට වැය වන විශාල විදුලි බලයෙන් 95% ක් පමණ ඉතිරි වන නිසා", "ඇලුමිනියම් උණු වීමට 3000°C අවශ්‍ය නිසා", "ඇලුමිනියම් පසෙන් අඩු නිසා", "ඇලුමිනියම් පහසුවෙන් මලකඩ කන නිසා", "පරණ බීම කෑන් උණු කර නැවත භාවිත කිරීම පරිසර හිතකාමී හා ලාභදායී වේ."),
    q("අපිරිසිදු තඹ ලෝහයේ සන්නායකතාව වැඩි කර පිරිසිදු කිරීමෙන් පසු ඇනෝඩය යට එකතු වන 'ඇනෝඩ මඩ' (Anode sludge) වල අඩංගු වටිනා ලෝහ මොනවාද?", "රන් (Au) සහ රිදී (Ag)", "සෝඩියම් සහ පොටෑසියම්", "සින්ක් සහ මැග්නීසියම්", "කැල්සියම් සහ ඇලුමිනියම්", "තඹට වඩා අඩු සක්‍රීය ලෝහ ඔක්සිකරණය නොවී ඇනෝඩයෙන් ගැලවී පතුලේ රැඳේ."),
    q("හයිඩ්‍රොකාබන ඉන්ධනයක් වන 'ජෛව වායුව' (Biogas) සත්ව අපද්‍රව්‍ය හා ශාක අපද්‍රව්‍යවලින් නිපදවීමේදී පද්ධතිය තිබිය යුත්තේ කුමන තත්ත්වයේද?", "වාතය රහිත (නිර්වායු) සංවෘත ටැංකියක් තුළ", "විවෘත වාතයේ හිරු එළියේ", "උතුරන ජලයේ", "සාන්ද්‍ර අම්ල තුළ", "මෙතනොජනික් නිර්වායු බැක්ටීරියා CH₄ හා CO₂ නිපදවයි."),
    q("කිසියම් ද්‍රව්‍යයක 'තන්‍යතාව' හා 'ලෝහමය දිස්නය' ඇති නමුත් එය කාමර උෂ්ණත්වයේදී ද්‍රවයක් ලෙස පවතින්නේ කුමන ලෝහයද?", "රසදිය (Hg)", "ගැලියම් (29.8°C දී ද්‍රව වේ)", "සෝඩියම්", "ඊයම්", "උෂ්ණත්වමාන හා බැරෝමීටරවල රසදිය භාවිත කෙරේ."),
    q("පහත දැක්වෙන රසායනික සමීකරණ අතුරින් ධාරා ඌෂ්මකයේ කැල්සියම් කාබනේට් තාප වියෝජනය නිවැරදිව දක්වන්නේ කුමක්ද?", "CaCO₃(s) → CaO(s) + CO₂(g)", "CaCO₃ + C → Ca + 2CO", "2CaCO₃ → 2Ca + 2CO₂ + O₂", "CaCO₃ + H₂O → CaO + CO₂", "ඉන්පසු සෑදෙන CaO වැලි (SiO₂) සමඟ ප්‍රතික්‍රියා කර CaSiO₃ සාදයි."),
    q("සබන් හා ඩිටර්ජන්ට් අධික ලෙස ජලාශවලට මුදා හැරීමෙන් සිදුවිය හැකි ප්‍රධාන පාරිසරික හානිය කුමක්ද?", "පොස්පේට් ඇතුළත් ඩිටර්ජන්ට් නිසා සුපෝෂණය ඇති වී ජලජ ජීවීන් මිය යාම", "ජලය හිම බවට පත්වීම", "ජලයේ උෂ්ණත්වය 0°C වීම", "වායුගෝලයේ ඔක්සිජන් දෙගුණ වීම", "වර්තමානයේ පොස්පේට් රහිත ජෛව හායනයට ලක්වන ඩිටර්ජන්ට් නිපදවයි."),
    q("දී ඇති හයිඩ්‍රොකාබන යුගල අතුරින් දැල්ලේ වැඩිපුරම කළු දැලි (අසම්පූර්ණ දහනය) ඇති කරමින් දැල්වෙන්නේ කුමක්ද?", "ඇල්කයින / ඇල්කීන (උදා: C₂H₂ හෝ C₂H₄)", "මීතේන් (CH₄)", "ඊතේන් (C₂H₆)", "හයිඩ්‍රජන්", "අසංතෘප්ත සංයෝගවල කාබන් ප්‍රතිශතය සාපේක්ෂව වැඩි බැවින් කහ-දැලි සහිත දැල්ලක් දෙයි."),
    q("වීදුරු, පිඟන් භාණ්ඩ හා සිමෙන්ති යන නිෂ්පාදන සියල්ලටම පොදුවේ අවශ්‍ය වන පෘථිවි කබොලේ බහුල අමුද්‍රව්‍යය කුමක්ද?", "සිලිකේට / සිලිකා (SiO₂)", "තඹ", "සෝඩියම් හයිඩ්‍රොක්සයිඩ්", "රබර්", "මැටි (ඇලුමිනෝ-සිලිකේට) හා වැලි (SiO₂) මෙම කර්මාන්තවල පදනම වේ."),
    q("ශ්‍රී ලංකාවේ මැණික් කර්මාන්තයේදී කැපීමට හා ඔප දැමීමට යොදා ගන්නා කොරන්ඩම් (Corundum - නිල් මැණික්/රතු මැණික්) රසායනිකව කුමන සංයෝගයද?", "ඇලුමිනියම් ඔක්සයිඩ් (Al₂O₃)", "සිලිකන් ඩයොක්සයිඩ්", "කැල්සියම් කාබනේට්", "කාබන්", "සුළු සංක්‍රාන්ති ලෝහ අපද්‍රව්‍ය (Cr, Fe, Ti) නිසා මැණික්වලට විවිධ වර්ණ ලැබේ."),
    q("කිසියම් බහුඅවයවිකයක් පොලිමර් දාම අතර ප්‍රබල සහසංයුජ හරස් බන්ධන සහිත ත්‍රිමාණ ජාලයක් සාදා ඇත්නම් එහි ගුණය කුමක්ද?", "රත් කළ විට උණු නොවන තාප දෘඪ ගුණය", "පහසුවෙන් උණු වී ඇදෙන ගුණය", "ජලයේ දියවීම", "වාෂ්ප වීම", "විදුලි ප්ලග්, ස්විච් හා පීනෝල්-ෆෝමැල්ඩිහයිඩ් (බේක්ලයිට්) මීට උදාහරණ වේ."),
    q("වැසි ජලයේ pH අගය ස්වභාවිකවම 5.6 ක් පමණ වුවද, කර්මාන්තශාලා ආසන්නයේ එය pH 3.5 දක්වා අඩු වීමට ප්‍රධාන හේතුව කුමක්ද?", "SO₂ සහ NO₂ වායු වැසි ජලයේ දිය වීම", "O₂ වායුව දිය වීම", "NH₃ වායුව දිය වීම", "CaCO₃ දිය වීම", "මෙමඟින් පසේ ඛනිජ සේදී ගොස් ශාක මුල්වලට හානි සිදුවේ."),
    q("වීදුරු පාත්‍රයක ඇති කළු ග්‍රැෆයිට් හෝ දියමන්ති වෙනුවට තඹ හා ඇලුමිනියම් ප්‍රතිචක්‍රීකරණය කිරීමේදී මුලින්ම ලෝහ වෙන් කිරීමට යකඩ වෙන් කරගන්නේ කෙසේද?", "ප්‍රබල විද්‍යුත් චුම්භකයක් භාවිතයෙන්", "ජලයේ ගිල්වීමෙන්", "අම්ලයක දිය කිරීමෙන්", "පෙරීමෙන්", "යකඩ හා වානේ චුම්භකයට ආකර්ෂණය වන අතර ඇලුමිනියම් හා තඹ ආකර්ෂණය නොවේ."),
    q("සෝඩියම් ස්ටියරේට් (සබන්) ක්ෂාරීය ස්වභාවයක් දරන්නේ එය සෑදී ඇත්තේ කුමන ආකාරයේ අම්ලයකින් හා භෂ්මයකින්ද?", "දුබල මේද අම්ලයකින් සහ ප්‍රබල භෂ්මයකින් (NaOH)", "ප්‍රබල අම්ලයකින් සහ දුබල භෂ්මයකින්", "ප්‍රබල අම්ලයකින් සහ ප්‍රබල භෂ්මයකින්", "උදාසීන ජලයෙන්", "දුබල අම්ල-ප්‍රබල භෂ්ම ලවණ ජලීය ද්‍රාවණයේදී මඳක් භාෂ්මික වේ."),
    q("රබර් වල්කනයිස් කිරීම නොකළ ස්වාභාවික රබර්වල ප්‍රධාන දුර්වලතාවක් වන්නේ කුමක්ද?", "උණුසුම් කාලගුණයේදී මෘදු වී ඇලෙන සුලු වීම හා සීතලේදී බිඳෙනසුලු වීම", "වතුරේ දියවීම", "මලකඩ කෑම", "විදුලිය සන්නයනය කිරීම", "වල්කනයිස් කළ රබර් වාහන ටයර් හා සපත්තු අඩි සෑදීමට යොදා ගනී."),
    q("ලෝහ කර්මාන්තයේදී 'ටින් ප්ලේටින්' (Tin plating - ආහාර ටින් ඇතුළත ටින් ආලේප කිරීම) සඳහා ටින් ලෝහය යොදා ගන්නේ ඇයි?", "ටින් විෂ රහිත වීම සහ ආහාරවල ඇති දුබල අම්ල සමඟ ප්‍රතික්‍රියා නොකිරීම", "ටින් ඉතා ලාභ හා පුපුරනසුලු වීම", "ටින් යකඩවලට වඩා සක්‍රීය වීම", "ටින් ජලයේ දියවීම", "ටින් ස්තරය සීරුණහොත් යකඩ ටින්වලට වඩා සක්‍රීය නිසා ඉක්මනින් මලකඩ කන බැවින් පිපුණු ටින් ආහාර නොගත යුතුය."),
    q("සෝඩියම් හා පොටෑසියම් ලෝහ වෙනුවට වාහනවල කොටස් හා උපකරණ තැනීමට ඇලුමිනියම් හා යකඩ යොදා ගැනීමට හේතුව කුමක්ද?", "Al හා Fe ඉහළ ශක්තියක්, ඉහළ ද්‍රවාංකයක් සහ වාතය/ජලය සමඟ ප්‍රබලව ප්‍රතික්‍රියා නොකිරීම", "Na හා K වල ද්‍රවාංකය 3000°C වීම", "Fe ජලයේ පාවීම", "Al වායුවක් වීම", "ක්ෂාර ලෝහ ඉතා මෘදු හා අධික සක්‍රීය නිසා ව්‍යුහාත්මක ද්‍රව්‍ය ලෙස භාවිත කළ නොහැක."),
    q("ශ්‍රී ලංකාවේ බහුලව භාවිත වන 'කාබනික පොහොර' නිෂ්පාදනයේදී රසායනික පොහොරවලට සාපේක්ෂව පවතින වාසිය කුමක්ද?", "පසේ ව්‍යුහය හා ජල රඳවා ගැනීම වැඩි දියුණු කර ක්ෂුද්‍රජීවීන්ට හිතකර වීම", "වැඩි වේගයෙන් ජලය දූෂණය කිරීම", "පස ආම්ලික කිරීම", "පසේ හියුමස් ඉවත් කිරීම", "කාබනික පොහොරවල පෝෂක සෙමෙන් මුදා හැරෙන බැවින් පස සරු වේ."),
    q("වීදුරු පාත්‍රයක ඇති C₂H₄, C₂H₂, CH₄ සහ C₆H₆ අතරින් ප්‍රතිශතයක් ලෙස වැඩිම හයිඩ්‍රජන් ස්කන්ධයක් අඩංගු හයිඩ්‍රොකාබනය කුමක්ද?", "මීතේන් (CH₄)", "එතීන් (C₂H₄)", "ඉතයින් (C₂H₂)", "බෙන්සීන් (C₆H₆)", "මීතේන්වල 4/16 = 25% ක් හයිඩ්‍රජන් වේ (අනෙක්වා ඊට අඩුය)."),
    q("කිසියම් ලෝහයක් හයිඩ්‍රජන්ට වඩා අඩු සක්‍රීයතාවක් ඇති නමුත් හොඳ තාප හා විද්‍යුත් සන්නායකයකි. එය තඹ ද්‍රාවණ සමඟ නොව HNO₃ සමඟ පමණක් ප්‍රතික්‍රියා කරයි නම් කවර ලෝහය විය හැකිද?", "තඹ (Cu)", "මැග්නීසියම් (Mg)", "සින්ක් (Zn)", "පොටෑසියම් (K)", "තඹ තනුක HCl සමඟ ප්‍රතික්‍රියා නොකරන නමුත් ඔක්සිකාරක නයිට්‍රික් අම්ලය සමඟ ප්‍රතික්‍රියා කරයි."),
    q("කෘත්‍රිම රෙදිපිළි කර්මාන්තයේදී භාවිත කරන පොලියෙස්ටර් (ටෙරිලීන්) හා නයිලෝන් යන බහුඅවයවික සෑදෙන ප්‍රතික්‍රියා වර්ගය කුමක්ද?", "සංඝනීභවන බහුඅවයවීකරණය (Condensation polymerization)", "ආකලන බහුඅවයවීකරණය", "වියෝජනය", "උදාසීනීකරණය", "සංඝනීභවන බහුඅවයවීකරණයේදී H₂O වැනි කුඩා අණු පිටවෙමින් බහුඅවයවික සෑදේ."),
    q("පෙට්‍රල්වලට වඩා ඩීසල් ඉන්ධනයේ අඩංගු හයිඩ්‍රොකාබන අණුවල ප්‍රධාන වෙනස කුමක්ද?", "ඩීසල්වල කාබන් දාම දිගින් වැඩි (C₁₄–C₂₀) හා තාපාංකය ඉහළ වීම", "ඩීසල් වායුවක් වීම", "ඩීසල්වල කාබන් 1 ක් පමණක් තිබීම", "ඩීසල් ජලයේ දියවීම", "පෙට්‍රල් C₅–C₁₀ පමණ කුඩා හයිඩ්‍රොකාබනවලින් සමන්විත වේ."),
    q("ශ්‍රී ලංකාවේ බහුලව හමුවන මිනිරන් (Graphite) ඛනිජය බෝගල හා කහටගහ පතල්වලින් ලබා ගැනේ. එහි ප්‍රධාන කාර්මික භාවිතයක් වන්නේ කුමක්ද?", "වියළි කෝෂ ඉලෙක්ට්‍රෝඩ, ලිහිසිකාරක හා පැන්සල් කූරු", "වීදුරු කැපීම", "ආහාර පරිරක්ෂණය", "පොහොර සෑදීම", "ශ්‍රී ලංකාවේ නහර මිනිරන් (Vein graphite) ලෝකයේ ඉහළම සංශුද්ධතාවයකින් යුක්ත වේ."),
    q("එකම කාබන් පරමාණු 2 ක් ඇති නමුත් වෙනස් රසායනික ගුණ පෙන්වන CH₃-CH₃ (ඊතේන්) හා CH₂=CH₂ (එතීන්) අතර ප්‍රධාන ව්‍යුහාත්මක වෙනස කුමක්ද?", "ඊතේන්හි C-C ඒක බන්ධනයක් ද එතීන්හි C=C ද්විත්ව බන්ධනයක් ද තිබීම", "ඊතේන්හි ඔක්සිජන් තිබීම", "එතීන් ලෝහයක් වීම", "ඊතේන්හි කාබන් 4 ක් තිබීම", "ද්විත්ව බන්ධනය එතීන්වල ඉහළ ප්‍රතික්‍රියාශීලීතාවට හේතු වේ."),
    q("සාමාන්‍යයෙන් PVC පයිප්ප ගිනි තැබූ විට ඇතිවන පාරිසරික අවදානම පොලිතීන්වලට වඩා දරුණු වන්නේ ඇයි?", "PVC වල ක්ලෝරීන් අඩංගු බැවින් HCl වායුව හා විෂ සහිත ඩයොක්සීන් පිටවීම", "PVC කිසිදා නොදැවෙන නිසා", "PVC ඔක්සිජන් පිට කරන නිසා", "PVC ජලය සාදන නිසා", "එබැවින් ප්ලාස්ටික් හා PVC ගිනි තැබීම සම්පූර්ණයෙන් නතර කළ යුතුය."),
    q("ජලයේ තාවකාලික කඨිනත්වය ඉවත් කිරීමට රත් කිරීම හැරුණු විට 'නිවූ හුණු' (Ca(OH)₂) නියමිත ප්‍රමාණයෙන් එක් කළ හැකි ක්‍රමය හඳුන්වන්නේ කෙසේද?", "ක්ලාක්ගේ ක්‍රමය (Clark's process)", "හේබර් ක්‍රමය", "ඩවුන්ස් ක්‍රමය", "ස්පර්ශ ක්‍රමය", "Ca(HCO₃)₂ + Ca(OH)₂ → 2CaCO₃↓ + 2H₂O."),
    q("ඇලුමිනියම් තහඩු මලකඩ නොකා දීප්තිමත්ව හා ශක්තිමත්ව තබා ගැනීමට ඒවා මත Al₂O₃ ස්තරය විද්‍යුත් රසායනිකව ඝන කිරීමේ ක්‍රියාවලිය කුමක්ද?", "ඇනෝඩීකරණය (Anodizing)", "ගැල්වනයිස් කිරීම", "වල්කනයිස් කිරීම", "පැස්ටරීකරණය", "මෙහිදී ඇලුමිනියම් භාණ්ඩය ඇනෝඩය ලෙස සම්බන්ධ කර තනුක සල්ෆියුරික් අම්ලයේ විද්‍යුත් විච්ඡේදනය කෙරේ."),
    q("කිසියම් ලෝහ ඔක්සයිඩයක් වන Fe₂O₃ කුඩු සහ ඇලුමිනියම් කුඩු මිශ්‍ර කර දැල්වූ විට අධික තාපයකින් ද්‍රව යකඩ සෑදීමේ ප්‍රතික්‍රියාව (දුම්රිය පීලි පෑස්සීමට) කුමක්ද?", "තර්මයිට් ප්‍රතික්‍රියාව (Thermite reaction)", "උදාසීනීකරණය", "පැසීම", "භාගික ආසවනය", "Fe₂O₃ + 2Al → Al₂O₃ + 2Fe + අධික තාපය."),
    q("තනි භාවිත ප්ලාස්ටික් අවම කිරීම සඳහා පොලිතීන් ඇසුරුම්වල ඝනත්වය හා ඝනකම නියාමනය කිරීමේදී මයික්‍රෝන 20 ට අඩු ලන්ච් ෂීට් තහනම් කර ඇත්තේ ඇයි?", "ප්‍රතිචක්‍රීකරණය කිරීමට අපහසු වී සුළඟින් පරිසරයේ පැතිරී සතුන් ආහාරයට ගැනීම වැළැක්වීමට", "ඒවා ඉතා බර වීම නිසා", "ඒවායේ යකඩ ඇති නිසා", "ඒවා ගිනි නොගන්නා නිසා", "නැවත භාවිත කළ හැකි රෙදි බෑග් හා ජෛව හායන දවටන වඩාත් සුදුසුය."),
    q("වීදුරු පාත්‍රයක ඇති කාබනික සංයෝග අතරින් විසප්පු නොවී හඳුනාගත හැකි ඇසිටිලීන් හෙවත් ඉතයින්වල පොදු සූත්‍රය අයත් වන්නේ කුමන ශ්‍රේණියටද?", "CₙH₂ₙ₋₂ (ඇල්කයින ශ්‍රේණිය)", "CₙH₂ₙ₊₂", "CₙH₂ₙ", "CₙH₂ₙ₊₁OH", "n = 2 විට C₂H₂(₂)₋₂ = C₂H₂ ලැබේ."),
    q("ස්වභාවික රබර් කිරි ගස්වලින් එකතු කළ පසු ක්ෂණිකව කැටි ගැසීම වැළැක්වීම සඳහා එක් කරන ස්ථායීකාරක රසායනික ද්‍රව්‍යය කුමක්ද?", "ඇමෝනියා ද්‍රාවණය (NH₃)", "ෆෝමික් අම්ලය", "විනාකිරි", "සල්ෆියුරික් අම්ලය", "ඇමෝනියා භාෂ්මික බැවින් බැක්ටීරියා මගින් අම්ල සෑදීම වළක්වා රබර් කිරි ද්‍රවව තබයි."),
    q("කිසියම් ලෝහයක ශුද්ධතාව නොව 'ඝනත්වය අඩු බව හා විඛාදන ප්‍රතිරෝධය' නිසා ආහාර ඇසුරුම් (Foil) සහ පානීය කෑන් සෑදීමට වඩාත්ම භාවිත වන්නේ කුමන ලෝහයද?", "ඇලුමිනියම් (Al)", "ඊයම් (Pb)", "තඹ (Cu)", "රසදිය (Hg)", "ඇලුමිනියම් සැහැල්ලු, විෂ නොවන හා ආහාර කල් තබා ගැනීමට සුදුසු ලෝහයකි."),
    q("ඛනිජ තෙල් පිරිපහදු කිරීමේදී භාගික කුළුණේ ඉහළ සිට පහළට යන විට එක් එක් භාගයේ ස්වභාවය වෙනස් වන්නේ කෙසේද?", "තාපාංකය, දුස්ස්‍රාවිතාව (උකු බව) හා අණුක ස්කන්ධය වැඩි වේ", "තාපාංකය අඩු වේ", "වාෂ්පශීලී බව වැඩි වේ", "ඉක්මනින් දැල්වෙනසුලු බව වැඩි වේ", "ඉහළින් වායුමය කුඩා අණු ද පහළින් උකු ද්‍රව හා තාර ද වෙන් වේ."),
    q("සෝඩියම් ක්ලෝරයිඩ් ඝන, ජලය සහ ගෑස් ලිපක දැල්ලේ ඇති නිල් පැහැය පෙන්නුම් කරන්නේ කුමක්ද?", "සම්පූර්ණ දහනය (ප්‍රමාණවත් ඔක්සිජන් ලැබීම)", "අසම්පූර්ණ දහනය", "ඔක්සිජන් හිඟ වීම", "කාබන් මොනොක්සයිඩ් සෑදීම", "නිල් දැල්ල වැඩි තාපයක් නිපදවන අතර භාජනවල දැලි බැඳීමක් සිදු නොවේ."),
    q("පොල් තෙල් සබන් බවට හැරවීමේදී (Saponification) ඝන සබන් මතුපිට පාවී වෙන් කර ගැනීමට ද්‍රාවණයට එකතු කරන්නේ කුමක්ද?", "සාන්ද්‍ර සෝඩියම් ක්ලෝරයිඩ් (ලුණු) ද්‍රාවණය", "සීනි ද්‍රාවණය", "හුණු දියර", "භූමිතෙල්", "ලුණු එක් කිරීමෙන් (Salting out) සබන්වල ද්‍රාව්‍යතාව අඩු වී සබන් ඝන ස්තරයක් ලෙස වෙන් වේ."),
    q("කිසියම් ලෝහයකින් සෑදූ ද්‍රව්‍යයක් වන වානේවලට 'තැලීම හා පන්ච් කිරීම' (Tempered) මගින් ඉහළ දැඩි බවක් ලැබෙන්නේ කුමන සංඝටක දෙක නිසාද?", "යකඩ සහ කාබන්", "තඹ සහ ටින්", "ඊයම් සහ ටින්", "ඇලුමිනියම් සහ මැග්නීසියම්", "අධි කාබන් වානේ කැපුම් ආයුධ, කියත් හා මිටි සෑදීමට ගනී."),
    q("මූලද්‍රව්‍ය X කාබනික සංයෝග සෑදීමේදී දාම, අතු බෙදුණු දාම හා වළලු සාදයි. X යනු කුමන මූලද්‍රව්‍යයද?", "කාබන් (C)", "සෝඩියම් (Na)", "ක්ලෝරීන් (Cl)", "හීලියම් (He)", "කාබන් පරමාණු අතර ශක්තිමත් C-C සහසංයුජ බන්ධන සෑදීමේ හැකියාව මීට හේතුවයි."),
    q("වීදුරුවලට කොළ පැහැයක් ලැබෙන්නේ සාමාන්‍යයෙන් වැලිවල අඩංගු කුමන ලෝහ අපද්‍රව්‍යය නිසාද?", "යකඩ(II) සංයෝග (Fe²⁺)", "සෝඩියම්", "කැල්සියම්", "ඇලුමිනියම්", "තද නිල් වීදුරු සඳහා කොබෝල්ට් ඔක්සයිඩ් ද අධි තාප ප්‍රතිරෝධී පයිරෙක්ස් වීදුරු සඳහා බෝරෝන් ඔක්සයිඩ් ද යොදයි."),
    q("තඹ, ඇලුමිනියම්, යකඩ සහ මැග්නීසියම් අතුරින් වඩාත්ම කාර්යක්ෂමව හා වැඩිම පරිමාවකින් ගොඩනැගිලි ඉදිකිරීම් හා පාලම් සෑදීමට යොදා ගන්නා ලෝහය කුමක්ද?", "යකඩ (වානේ ලෙස)", "මැග්නීසියම්", "තඹ", "සෝඩියම්", "යකඩ බහුල බව, අඩු මිල හා ඉහළ ආතන්‍ය ශක්තිය මීට හේතු වේ."),
    q("විද්‍යුත් ධාරාව සන්නයනය කිරීමට යොදා ගන්නා කේබල්වල ඇතුළත තඹ කම්බි වටා PVC යොදා ඇත්තේ PVC හි කුමන ගුණය නිසාද?", "විද්‍යුත් පරිවාරක බව හා නම්‍යශීලී බව", "විද්‍යුත් සන්නායක බව", "තාප සන්නායක බව", "ජලයේ දියවන බව", "විදුලි සැර වැදීම හා කෙටි පරිපථ වීම PVC ආවරණයෙන් වළකයි."),
    q("කිසියම් ලෝහයක නයිට්‍රේට් ලවණය රත් කළ විට ලෝහය, NO₂ සහ O₂ බවට සම්පූර්ණයෙන් වියෝජනය වන්නේ සක්‍රියතා ශ්‍රේණියේ ඉතා පහළින් ඇති කුමන ලෝහයද?", "රිදී නයිට්‍රේට් (AgNO₃)", "සෝඩියම් නයිට්‍රේට්", "කැල්සියම් නයිට්‍රේට්", "සින්ක් නයිට්‍රේට්", "2AgNO₃ → 2Ag + 2NO₂ + O₂ (රිදී ඔක්සයිඩ් පවා තාපයට අස්ථායී නිසා රිදී ලැබේ).")
  )
}
